const express = require('express');
const crypto = require('crypto');
const { Pool } = require('pg');

const app = express();
app.use(express.json());

const pool = new Pool({ connectionString: process.env.DATABASE_URL });

// Middleware: extract tenant and user from verified JWT (already validated upstream)
function authMiddleware(req, res, next) {
  // JWT already verified by API gateway; claims are in x-auth-* headers
  req.tenantId = req.headers['x-auth-tenant-id'];
  req.userId = req.headers['x-auth-user-id'];
  req.userRole = req.headers['x-auth-role'];
  if (!req.tenantId || !req.userId) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  next();
}

app.use(authMiddleware);

// Tenant-scoped query builder
class TenantQueryBuilder {
  constructor(tenantId) {
    this.tenantId = tenantId;
    this.filters = [{ field: 'tenant_id', value: tenantId }];
  }

  addFilter(field, value) {
    this.filters.push({ field, value });
    return this;
  }

  buildSelect(table, columns = '*') {
    const conditions = this.filters.map((f, i) => `${f.field} = $${i + 1}`);
    const values = this.filters.map(f => f.value);
    return {
      text: `SELECT ${columns} FROM ${table} WHERE ${conditions.join(' AND ')}`,
      values
    };
  }
}

// Resource ownership verification
async function verifyResourceOwnership(resourceId, resourceType, tenantId) {
  const query = {
    text: `SELECT tenant_id FROM ${resourceType} WHERE id = $1`,
    values: [resourceId]
  };
  const result = await pool.query(query);
  if (result.rows.length === 0) return false;
  return result.rows[0].tenant_id === tenantId;
}

// Document sharing: cross-tenant sharing via share tokens
async function resolveDocumentAccess(documentId, requestingTenantId, shareToken) {
  // First check: is the document in the requesting tenant's scope?
  const directAccess = await verifyResourceOwnership(documentId, 'documents', requestingTenantId);
  if (directAccess) return { allowed: true, accessType: 'owner' };

  // Second check: is there a valid share token?
  if (shareToken) {
    const shareQuery = {
      text: `SELECT target_tenant_id, permissions FROM document_shares WHERE document_id = $1 AND share_token = $2 AND expires_at > NOW()`,
      values: [documentId, shareToken]
    };
    const shareResult = await pool.query(shareQuery);
    if (shareResult.rows.length > 0) {
      const share = shareResult.rows[0];
      if (share.target_tenant_id === requestingTenantId || share.target_tenant_id === null) {
        return { allowed: true, accessType: 'shared', permissions: share.permissions };
      }
    }
  }

  return { allowed: false };
}

// GET /api/v1/documents/:id - Retrieve a document
app.get('/api/v1/documents/:id', async (req, res) => {
  try {
    const documentId = req.params.id;
    const shareToken = req.query.share_token || null;

    const access = await resolveDocumentAccess(documentId, req.tenantId, shareToken);
    if (!access.allowed) {
      return res.status(404).json({ error: 'Document not found' });
    }

    const query = {
      text: 'SELECT id, title, content, created_by, created_at, updated_at FROM documents WHERE id = $1',
      values: [documentId]
    };
    const result = await pool.query(query);
    if (result.rows.length === 0) {
      return res.status(404).json({ error: 'Document not found' });
    }

    res.json({ document: result.rows[0], accessType: access.accessType });
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// GET /api/v1/documents/:id/comments - List comments on a document
app.get('/api/v1/documents/:id/comments', async (req, res) => {
  try {
    const documentId = req.params.id;
    const shareToken = req.query.share_token || null;

    const access = await resolveDocumentAccess(documentId, req.tenantId, shareToken);
    if (!access.allowed) {
      return res.status(404).json({ error: 'Document not found' });
    }

    const qb = new TenantQueryBuilder(req.tenantId);
    qb.addFilter('document_id', documentId);
    const query = qb.buildSelect('comments', 'id, author_id, body, created_at');
    const result = await pool.query(query);

    res.json({ comments: result.rows });
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// PUT /api/v1/documents/:docId/comments/:commentId - Update a comment
app.put('/api/v1/documents/:docId/comments/:commentId', async (req, res) => {
  try {
    const { docId, commentId } = req.params;
    const { body } = req.body;

    if (!body || typeof body !== 'string' || body.length > 10000) {
      return res.status(400).json({ error: 'Invalid comment body' });
    }

    // Verify document access
    const access = await resolveDocumentAccess(docId, req.tenantId, null);
    if (!access.allowed) {
      return res.status(404).json({ error: 'Document not found' });
    }

    // Verify comment belongs to the document, tenant, and user owns it
    const commentCheck = {
      text: 'SELECT id, author_id, document_id, tenant_id FROM comments WHERE id = $1 AND document_id = $2 AND tenant_id = $3',
      values: [commentId, docId, req.tenantId]
    };
    const commentResult = await pool.query(commentCheck);
    if (commentResult.rows.length === 0) {
      return res.status(404).json({ error: 'Comment not found' });
    }

    const comment = commentResult.rows[0];
    // Authorization: user must be the author OR an admin
    if (comment.author_id !== req.userId && req.userRole !== 'admin') {
      return res.status(403).json({ error: 'Forbidden' });
    }

    const updateQuery = {
      text: 'UPDATE comments SET body = $1, updated_at = NOW() WHERE id = $2 AND tenant_id = $3 RETURNING id, body, updated_at',
      values: [body, commentId, req.tenantId]
    };
    const updateResult = await pool.query(updateQuery);

    res.json({ comment: updateResult.rows[0] });
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// DELETE /api/v1/documents/:docId/comments/:commentId - Delete a comment
app.delete('/api/v1/documents/:docId/comments/:commentId', async (req, res) => {
  try {
    const { docId, commentId } = req.params;

    // Verify document access
    const access = await resolveDocumentAccess(docId, req.tenantId, null);
    if (!access.allowed) {
      return res.status(404).json({ error: 'Document not found' });
    }

    // Fetch comment - verify it belongs to the document AND tenant
    const commentCheck = {
      text: 'SELECT id, author_id, tenant_id FROM comments WHERE id = $1 AND document_id = $2 AND tenant_id = $3',
      values: [commentId, docId, req.tenantId]
    };
    const commentResult = await pool.query(commentCheck);
    if (commentResult.rows.length === 0) {
      return res.status(404).json({ error: 'Comment not found' });
    }

    const comment = commentResult.rows[0];
    if (comment.author_id !== req.userId && req.userRole !== 'admin') {
      return res.status(403).json({ error: 'Forbidden' });
    }

    await pool.query('DELETE FROM comments WHERE id = $1 AND tenant_id = $2', [commentId, req.tenantId]);
    res.status(204).send();
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Internal server error' });
  }
});

module.exports = app;
